#if UNITY_EDITOR
using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using HauntedFish.Theatre;
// STAGED OUTSIDE ASSETS. No automatic invocation or persistent save.
public static class TheatreSilhouetteRefinement {
 public static void ApplyAfterGrant(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating||PrefabStageUtility.GetCurrentPrefabStage()!=null)throw new Exception("Exclusive idle native window required");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/theatre.unity"||scene.isDirty)throw new Exception("Clean authored theatre scene required");var presentation=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<TheatrePresentation>(true)).Single();var s=new SerializedObject(presentation);var camera=(Camera)s.FindProperty("_Camera").objectReferenceValue;var walker=(Transform)s.FindProperty("_Walker").objectReferenceValue;var own=(SpriteRenderer)s.FindProperty("_OwnSilhouette").objectReferenceValue;if(!camera||!camera.orthographic||Mathf.Abs(camera.orthographicSize-10)>.01f)throw new Exception("Measured 20-unit orthographic framing changed; remeasure before applying");var before=walker.localPosition;var exit=presentation.GetComponentsInChildren<Transform>(true).Single(t=>t.name.StartsWith("EXIT - far left"));var exitPose=exit.localPosition;var box=exit.GetComponent<BoxCollider>();var center=box.center;var size=box.size;var seats=presentation.transform.Find("SEATING - authored cloud chairs, no collision");if(!seats)throw new Exception("Verified native chair row missing");var chairMatrices=seats.GetComponentsInChildren<Transform>(true).Select(t=>new {t,m=t.localToWorldMatrix}).ToArray();
 // Version3 native screenshot720px spans20world units. 100px lift = 2.7778units.
 // Absolute values make repeated invocation idempotent. Only visual children move.
 float lift=2*camera.orthographicSize*(100f/720f);var p=own.transform.localPosition;p.y=-.3f+lift;own.transform.localPosition=p;
 foreach(string name in new[]{"Seated fish audience left","Seated ghost audience right"}){var sprite=presentation.GetComponentsInChildren<SpriteRenderer>(true).Single(r=>r.name==name);p=sprite.transform.localPosition;p.y=2.4f+lift;sprite.transform.localPosition=p;if(sprite.color!=Color.black)throw new Exception("Silhouette black material/color changed");}
 if(own.color!=Color.black||walker.localPosition!=before||exit.localPosition!=exitPose||box.center!=center||box.size!=size)throw new Exception("Owned lane/exit/color changed");foreach(var chair in chairMatrices)if(chair.t.localToWorldMatrix!=chair.m)throw new Exception("Physical chair placement changed");if(presentation.GetComponentsInChildren<Canvas>(true).Any(c=>c.enabled))throw new Exception("Theatre UI must remain hidden");EditorSceneManager.MarkSceneDirty(scene); // Real decoded fish+ghost captures and contrast review BEFORE explicit save.
 }
}
#endif
